<template id="ff-global-cms-editor-template">
  <div class="ff-cms-editor" data-ff-editor>
    <div class="ff-ribbon" role="toolbar" aria-label="Global CMS Editor">
      <div class="ff-tabs">
        <button type="button" class="ff-tab active" data-tab="home">Home</button>
        <button type="button" class="ff-tab" data-tab="insert">Insert</button>
        <button type="button" class="ff-tab" data-tab="view">View</button>
        <span class="ff-status"><strong data-status-block>Paragraph</strong><span>•</span><span data-status-size>—</span></span>
      </div>
      <div class="ff-panel active" data-panel="home">
        <div class="ff-group"><button type="button" class="ff-command" data-action="undo"><i class="fa-solid fa-rotate-left"></i><span>Undo</span></button><button type="button" class="ff-command" data-action="redo"><i class="fa-solid fa-rotate-right"></i><span>Redo</span></button><small>Clipboard</small></div>
        <div class="ff-group"><div class="ff-row"><select data-format title="Styles"><option value="p">Paragraph</option><option value="h1">Heading 1</option><option value="h2">Heading 2</option><option value="h3">Heading 3</option><option value="h4">Heading 4</option><option value="h5">Heading 5</option><option value="h6">Heading 6</option><option value="blockquote">Quote</option><option value="pre">Code</option></select><select data-font title="Font"><option>Arial</option><option>Georgia</option><option>Tahoma</option><option>Times New Roman</option><option>Verdana</option></select><select data-size title="Font size"><option value="">Size</option><option value="2">Small</option><option value="3">Normal</option><option value="4">Large</option><option value="5">X-Large</option><option value="6">Huge</option></select></div><div class="ff-row"><button type="button" class="ff-icon" data-action="bold"><b>B</b></button><button type="button" class="ff-icon" data-action="italic"><i>I</i></button><button type="button" class="ff-icon" data-action="underline"><u>U</u></button><button type="button" class="ff-icon" data-action="strikeThrough"><s>S</s></button><label class="ff-color"><i class="fa-solid fa-font"></i><input type="color" data-fore value="#dff6fb"></label><label class="ff-color"><i class="fa-solid fa-highlighter"></i><input type="color" data-highlight value="#17323b"></label></div><small>Font</small></div>
        <div class="ff-group"><div class="ff-row"><button type="button" class="ff-icon" data-action="justifyLeft"><i class="fa-solid fa-align-left"></i></button><button type="button" class="ff-icon" data-action="justifyCenter"><i class="fa-solid fa-align-center"></i></button><button type="button" class="ff-icon" data-action="justifyRight"><i class="fa-solid fa-align-right"></i></button><button type="button" class="ff-icon" data-action="justifyFull"><i class="fa-solid fa-align-justify"></i></button></div><div class="ff-row"><button type="button" class="ff-icon" data-action="insertUnorderedList"><i class="fa-solid fa-list"></i></button><button type="button" class="ff-icon" data-action="insertOrderedList"><i class="fa-solid fa-list-ol"></i></button><button type="button" class="ff-icon" data-action="outdent"><i class="fa-solid fa-outdent"></i></button><button type="button" class="ff-icon" data-action="indent"><i class="fa-solid fa-indent"></i></button></div><small>Paragraph</small></div>
        <div class="ff-group"><button type="button" class="ff-command" data-action="removeFormat"><i class="fa-solid fa-eraser"></i><span>Clear<br>formatting</span></button><small>Editing</small></div>
      </div>
      <div class="ff-panel" data-panel="insert">
        <div class="ff-group"><button type="button" class="ff-command" data-insert="link"><i class="fa-solid fa-link"></i><span>Link</span></button><button type="button" class="ff-command" data-insert="media"><i class="fa-solid fa-photo-film"></i><span>Media</span></button><button type="button" class="ff-command" data-insert="image-url"><i class="fa-solid fa-image"></i><span>Image URL</span></button><button type="button" class="ff-command" data-insert="video-url"><i class="fa-solid fa-link"></i><span>Video URL</span></button><button type="button" class="ff-command" data-insert="table"><i class="fa-solid fa-table"></i><span>Table</span></button><small>Media</small></div>
        <div class="ff-group"><button type="button" class="ff-command" data-insert="button"><i class="fa-solid fa-square-up-right"></i><span>Button</span></button><button type="button" class="ff-command" data-insert="columns"><i class="fa-solid fa-table-columns"></i><span>Columns</span></button><button type="button" class="ff-command" data-insert="gallery"><i class="fa-solid fa-images"></i><span>Gallery</span></button><button type="button" class="ff-command" data-insert="youtube"><i class="fa-brands fa-youtube"></i><span>YouTube</span></button><button type="button" class="ff-command" data-insert="facebook"><i class="fa-brands fa-facebook"></i><span>Facebook</span></button><small>Content</small></div>
        <div class="ff-group"><button type="button" class="ff-command" data-action="insertHorizontalRule"><i class="fa-solid fa-minus"></i><span>Horizontal<br>line</span></button><button type="button" class="ff-command" data-image-align="left"><i class="fa-solid fa-align-left"></i><span>Image left</span></button><button type="button" class="ff-command" data-image-align="center"><i class="fa-solid fa-align-center"></i><span>Image center</span></button><button type="button" class="ff-command" data-image-align="right"><i class="fa-solid fa-align-right"></i><span>Image right</span></button><small>Arrange</small></div>
      </div>
      <div class="ff-panel" data-panel="view">
        <div class="ff-group"><button type="button" class="ff-command" data-view="source"><i class="fa-solid fa-code"></i><span>HTML<br>source</span></button><button type="button" class="ff-command" data-view="preview"><i class="fa-solid fa-eye"></i><span>Preview</span></button><button type="button" class="ff-command" data-view="fullscreen"><i class="fa-solid fa-expand"></i><span>Fullscreen</span></button><small>View</small></div>
        <div class="ff-group ff-note"><i class="fa-solid fa-circle-info"></i><span>Global CMS Editor — the same publishing editor contract used by News &amp; Notices.</span><small>Editor</small></div>
      </div>
    </div>
    <div class="ff-editable" contenteditable="true" spellcheck="true"></div>
    <div class="ff-footer"><span data-count>0 words • 0 characters</span></div>
    <input type="file" data-media-input hidden multiple accept="image/jpeg,image/png,image/webp,image/gif,video/mp4,video/webm,video/quicktime">
    <input type="file" data-gallery-input hidden multiple accept="image/jpeg,image/png,image/webp,image/gif">
    <div class="ff-resize" aria-hidden="true"></div>
  </div>
</template>

@once
@push('styles')
<style>
.ff-cms-editor{border:1px solid var(--line);border-radius:14px;background:#061923;overflow:visible;position:relative;min-width:0}.ff-ribbon{position:relative;z-index:20;background:#071b25;border-bottom:1px solid rgba(104,204,235,.18);box-shadow:0 5px 14px rgba(0,0,0,.2)}.ff-tabs{display:flex;align-items:center;gap:2px;min-height:40px;padding:0 7px;border-bottom:1px solid rgba(104,204,235,.13);overflow-x:auto;scrollbar-width:none}.ff-tabs::-webkit-scrollbar{display:none}.ff-tab{height:40px;padding:0 14px;border:0;border-bottom:2px solid transparent;background:transparent;color:#91aeb8;font-size:11px;font-weight:700;cursor:pointer}.ff-tab.active{color:#eaf8fb;border-bottom-color:#43c2e5;background:rgba(67,194,229,.08)}.ff-status{margin-left:auto;display:flex;gap:6px;align-items:center;color:#7898a3;font-size:9px;padding:5px 8px;border:1px solid rgba(104,204,235,.12);border-radius:7px;white-space:nowrap}.ff-status strong{color:#cfeaf0}.ff-panel{display:none;align-items:stretch;min-width:0;width:100%;overflow-x:auto;overflow-y:hidden;scrollbar-width:thin;-webkit-overflow-scrolling:touch}.ff-panel.active{display:flex}.ff-group{position:relative;flex:0 0 auto;display:flex;align-items:center;gap:3px;padding:5px 8px 18px;border-right:1px solid rgba(104,204,235,.12);min-height:58px}.ff-group:last-child{border-right:0}.ff-group>small{position:absolute;left:8px;right:8px;bottom:3px;text-align:center;color:#668791;font-size:8px;white-space:nowrap}.ff-row{display:flex;align-items:center;gap:3px;flex:0 0 auto}.ff-command,.ff-icon{border:1px solid transparent;border-radius:6px;background:transparent;color:#b7d0d7;cursor:pointer}.ff-command{min-width:42px;height:50px;padding:4px 7px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;font-size:8px}.ff-command i{font-size:14px;color:#9bc1cb}.ff-icon{width:31px;height:31px;display:inline-flex;align-items:center;justify-content:center;font-size:13px}.ff-command:hover,.ff-icon:hover,.ff-icon.active{background:rgba(67,194,229,.12);border-color:rgba(67,194,229,.25);color:#effbfe}.ff-group select{height:31px;border:1px solid rgba(104,204,235,.16);border-radius:5px;background:#061923;color:#c7e0e6;padding:0 7px;font-size:9px;outline:none}.ff-group select[data-format]{width:120px}.ff-group select[data-font]{width:112px}.ff-group select[data-size]{width:68px}.ff-color{width:31px;height:31px;display:inline-flex;align-items:center;justify-content:center;border:1px solid rgba(104,204,235,.16);border-radius:5px;position:relative;color:#b7d0d7}.ff-color input{position:absolute;inset:0;width:100%;height:100%;opacity:0}.ff-note{color:#7e9da6;font-size:10px;gap:8px;padding-right:20px}.ff-note i{color:#43c2e5}.ff-editable{min-height:320px;padding:18px;color:#e6f4f7;line-height:1.75;font-size:13px;outline:none;overflow-wrap:anywhere;word-break:break-word}.ff-editable.source-mode{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;white-space:pre-wrap}.ff-editable h1{font-size:30px}.ff-editable h2{font-size:24px}.ff-editable h3{font-size:19px}.ff-editable h4{font-size:17px}.ff-editable h5{font-size:15px}.ff-editable h6{font-size:13px;text-transform:uppercase}.ff-editable blockquote{margin:14px 0;padding:10px 16px;border-left:3px solid #43c2e5;background:rgba(67,194,229,.06);color:#b9d7df}.ff-editable pre{max-width:100%;overflow:auto;padding:12px;border:1px solid rgba(104,204,235,.16);border-radius:8px;background:#041017}.ff-editable table{width:100%;border-collapse:collapse;margin:14px 0}.ff-editable td,.ff-editable th{border:1px solid rgba(120,170,185,.35);padding:8px;text-align:left}.ff-editable th{background:rgba(67,194,229,.08)}.ff-editable img,.ff-editable video,.ff-editable iframe{max-width:100%;height:auto;border-radius:10px;margin:8px 0}.ff-editable iframe{width:100%;min-height:320px;border:0;background:#000}.ff-editable img.ff-selected{outline:2px solid #43c2e5;outline-offset:2px}.ff-editable img.ff-left{display:block;margin-right:auto}.ff-editable img.ff-center{display:block;margin-left:auto;margin-right:auto}.ff-editable img.ff-right{display:block;margin-left:auto}.ff-columns{display:grid;gap:16px;margin:16px 0}.ff-columns.cols-2{grid-template-columns:repeat(2,minmax(0,1fr))}.ff-columns.cols-3{grid-template-columns:repeat(3,minmax(0,1fr))}.ff-column{padding:15px;border:1px solid rgba(67,194,229,.14);border-radius:10px;background:rgba(67,194,229,.025);min-width:0}.ff-cta{display:inline-flex;align-items:center;justify-content:center;margin:8px 4px 8px 0;padding:10px 16px;border-radius:9px;background:#29aaca;color:#fff!important;text-decoration:none;font-weight:700}.ff-cta.outline{background:transparent;color:#29aaca!important;border:1px solid #29aaca}.ff-gallery{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px;margin:14px 0}.ff-gallery img{width:100%;aspect-ratio:16/10;object-fit:cover}.ff-footer{padding:7px 10px;border-top:1px solid var(--line);text-align:right;color:#7898a3;font-size:8px}.ff-resize{display:none;position:fixed;width:14px;height:14px;margin:-7px 0 0 -7px;border:2px solid #061923;border-radius:4px;background:#43c2e5;box-shadow:0 0 0 1px rgba(67,194,229,.55);z-index:10050;cursor:nwse-resize;touch-action:none}.ff-cms-editor.ff-fullscreen{position:fixed;inset:0;z-index:9999;background:#04151e;border-radius:0;display:flex;flex-direction:column}.ff-cms-editor.ff-fullscreen .ff-editable{flex:1;overflow:auto}.ff-cms-editor.ff-fullscreen .ff-ribbon{position:sticky;top:0}.ff-cms-editor.ff-fullscreen .ff-resize{z-index:10050}
@media(max-width:700px){.ff-tabs{min-height:38px}.ff-tab{height:38px;font-size:10px;padding:0 12px}.ff-status{display:none}.ff-panel{min-height:68px}.ff-group{padding-left:5px;padding-right:5px}.ff-command{min-width:38px;height:48px}.ff-group select[data-format]{width:104px}.ff-group select[data-font]{width:98px}.ff-group select[data-size]{width:64px}.ff-editable{font-size:16px;min-height:300px;padding:13px}.ff-editable .ff-columns{grid-template-columns:1fr!important}.ff-gallery{grid-template-columns:repeat(2,minmax(0,1fr))}.ff-editable table{display:block;overflow-x:auto}.ff-resize{width:16px;height:16px;margin:-8px 0 0 -8px}}
</style>
@endpush
@endonce
